commit 2308a45f5155c37dd279a5cfd0ba817974f46c98
Author: Mike Holownych <mike@holownych.com>
Date:   Wed Nov 11 05:01:08 2026 +0000

    fix(cli): a linked worktree whose .git was deleted is refused, not resolved to the main repository (pre-push review round 18)

    Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>

 cli/src/core/checkout_trust.ts   |  6 ++++++
 cli/test/worktrunk_trust.test.ts | 21 +++++++++++++++++++++
 docs/v1.1.4/FINDINGS.md          |  2 +-
 3 files changed, 28 insertions(+), 1 deletion(-)
2308a45f fix(cli): a linked worktree whose .git was deleted is refused, not resolved to the main repository (pre-push review round 18) (16 seconds ago) <Mike Holownych>
cli/src/core/checkout_trust.ts   |  6 ++++++
 cli/test/worktrunk_trust.test.ts | 21 +++++++++++++++++++++
 docs/v1.1.4/FINDINGS.md          |  2 +-
 3 files changed, 28 insertions(+), 1 deletion(-)

cli/src/core/checkout_trust.ts
  @@ -131,6 +131,12 @@ export function verifyCheckout(cwd: string): { reason?: string; gitDir?: string;
  +    // A registered linked worktree whose `.git` was DELETED has no `.git` at all: Git would find the enclosing repository
  +    // and act on it. Every directory between here and that repository is a candidate root.
  +    for (let dir = start; dir !== directories[0] && path.dirname(dir) !== dir; dir = path.dirname(dir)) {
  +      const missing = replacedWorktreeReason(dir);
  +      if (missing) return { reason: missing.replace("whose .git file was replaced by a repository", "whose .git file is missing") };
  +    }
       return {};
     }
     const planted = directories.find((dir) => inside(outer, dir));
  +6 -0

cli/test/worktrunk_trust.test.ts
  @@ -519,3 +519,24 @@ test("a session's --ai-message completer refuses an endpoint that a project .env
  +
  +test("a linked worktree whose .git file was deleted is refused, not resolved to the enclosing main repository", async () => {
  +  const { statusOf } = await import("../src/worktrunk/core.js");
  +  const { verifyCheckout } = await import("../src/core/checkout_trust.js");
  +  const f = fixture("feat/deleted");
  +  try {
  +    fs.writeFileSync(path.join(f.dir, "w.txt"), "w\n");
  +    fs.rmSync(path.join(f.dir, ".git"));
  +    fs.mkdirSync(path.join(f.dir, "sub"));
  +    assert.match(String(verifyCheckout(f.dir).reason), /whose \.git file is missing/);
  +    assert.match(String(verifyCheckout(path.join(f.dir, "sub")).reason), /whose \.git file is missing/, "from a subdirectory too");
  +    assert.throws(() => statusOf(f.dir), /not a trusted worktree/);
  +    const before = git(f.repo, "rev-parse", "HEAD");
  +    const merged = f.merge();
  +    assert.equal(merged.success, false, merged.output);
  +    assert.equal(git(f.repo, "rev-parse", "HEAD"), before, "the main checkout was not touched through the worktree");
  +    assert.equal(verifyCheckout(f.repo).reason, undefined, "the main checkout itself is fine");
  +    fs.mkdirSync(path.join(f.repo, "docs", "deeper"), { recursive: true });
  +    assert.equal(verifyCheckout(path.join(f.repo, "docs", "deeper")).reason, undefined, "an ordinary subdirectory of the main checkout is fine");
  +  } finally { f.cleanup(); }
  +});
  +21 -0

