100	 * when every `.git` file on the way up is a plain pointer to a Git directory OUTSIDE the outermost linked worktree
101	 * (outside what the agent can write) that points back at it (`gitdir` of a `<common>/worktrees/<name>` entry, or
102	 * `core.worktree` of a separate or submodule Git directory), and no repository with a real `.git` directory sits inside
103	 * a linked worktree. `gitDir`/`workTree` are the verified pair for the nearest `.git` file: Git is then run against them
104	 * directly, so a pointer rewritten after this check is not re-read.
105	 */
106	export function verifyCheckout(cwd: string): { reason?: string; gitDir?: string; workTree?: string } {
107	  let start: string;
108	  try { start = fs.realpathSync(cwd); } catch { return {}; }
109	  const files: string[] = [];
110	  const directories: string[] = [];
111	  for (let dir = start; ; dir = path.dirname(dir)) {
112	    try {
113	      if (fs.lstatSync(path.join(dir, ".git")).isDirectory()) directories.push(dir); else files.push(dir);
114	    } catch { /* no .git here */ }
115	    if (path.dirname(dir) === dir) break;
116	  }
117	  // The agent-writable boundary is the outermost LINKED worktree (its `.git` leads to `<common>/worktrees/<name>`). A
118	  // `.git` file above it (a bare-repository layout `project/.git` -> `.bare`) is the operator's, not the agent's.
119	  const isLinkedRoot = (root: string): boolean => {
120	    try {
121	      const content = readSmallFile(path.join(root, ".git"), MAX_POINTER_BYTES);
122	      const target = content === undefined ? undefined : parseGitfilePointer(content);
123	      return target !== undefined && path.basename(path.dirname(fs.realpathSync(path.resolve(root, target)))) === "worktrees";
124	    } catch { return false; }
125	  };
126	  const outer = [...files].reverse().find(isLinkedRoot) ?? files[files.length - 1];
127	  if (!outer) {
128	    // A plain repository (or none). But a registered linked worktree whose `.git` file the agent replaced by a repository
129	    // looks exactly like one: the main repository's worktree registry says it is not.
130	    for (const root of directories) {
131	      const replaced = replacedWorktreeReason(root);
132	      if (replaced) return { reason: replaced };
133	    }
134	    // A registered linked worktree whose `.git` was DELETED has no `.git` at all: Git would find the enclosing repository
135	    // and act on it. Every directory between here and that repository is a candidate root.
136	    for (let dir = start; dir !== directories[0] && path.dirname(dir) !== dir; dir = path.dirname(dir)) {
137	      const missing = replacedWorktreeReason(dir);
138	      if (missing) return { reason: missing.replace("whose .git file was replaced by a repository", "whose .git file is missing") };
139	    }
140	    return {};
141	  }
142	  const planted = directories.find((dir) => inside(outer, dir));
143	  if (planted) return { reason: `${planted} is a repository nested inside the linked worktree ${outer}` };
144	  let pinned: { gitDir: string; workTree: string } | undefined;
145	  for (const root of files.filter((candidate) => inside(outer, candidate))) {
146	    const dotGit = path.join(root, ".git");
147	    try {
148	      const content = readSmallFile(dotGit, MAX_POINTER_BYTES);
149	      if (content === undefined) return { reason: `${dotGit} is not a plain pointer file` };
150	      const target = parseGitfilePointer(content);
151	      if (target === undefined) return { reason: `${dotGit} is not a well-formed gitdir pointer` };
152	      const admin = fs.realpathSync(path.resolve(root, target));
153	      if (inside(outer, admin)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
154	      let pointsBack = false;
155	      if (path.basename(path.dirname(admin)) === "worktrees") {
156	        const common = fs.realpathSync(path.dirname(path.dirname(admin)));
157	        if (inside(outer, common)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
158	        const back = readSmallFile(path.join(admin, "gitdir"), MAX_POINTER_BYTES)?.trim();
159	        pointsBack = back !== undefined && fs.realpathSync(path.resolve(admin, back)) === path.join(root, ".git");
160	      } else {
161	        const configured = /^\s*worktree\s*=\s*(.+?)\s*$/m.exec(readSmallFile(path.join(admin, "config"), MAX_CONFIG_BYTES) ?? "");
