163	      }
164	      if (!pointsBack) return { reason: `the Git directory behind ${dotGit} does not point back at it` };
165	      pinned ??= { gitDir: admin, workTree: root };
166	    } catch {
167	      return { reason: `${dotGit} could not be verified` };
168	    }
169	  }
170	  return pinned ?? {};
171	}
