173	/** `git submodule status` lines as {path, initialised}; a path may contain spaces. */
174	export function parseSubmoduleStatus(listing: string): Array<{ path: string; initialised: boolean }> {
175	  const found: Array<{ path: string; initialised: boolean }> = [];
176	  for (const line of listing.split("\n")) {
177	    const match = /^(.)[0-9a-f]{40,64} (.*?)(?: \(.*\))?$/.exec(line);
178	    if (match) found.push({ path: match[2], initialised: match[1] !== "-" });
179	  }
180	  return found;
181	}
182	
183	/** The reason `cwd` is not a trusted checkout (see `verifyCheckout`), or undefined. */
184	export function untrustedCheckoutReason(cwd: string): string | undefined {
185	  return verifyCheckout(cwd).reason;
186	}
