1	/**
2	 * `nexus worktree merge` and `prune` (WP-1312).
3	 *
4	 * merge: commit what is dirty, squash, rebase onto the target, fast-forward only, then remove the worktree and its
5	 * branch. Nothing here runs a hook or an external command (commit messages are deterministic unless `--message` or
6	 * `--ai-message` supplies one). `mergeSeams.preMerge` below is called once after every refusal (a test seam for now).
7	 */
8	import * as fs from "node:fs";
9	import * as path from "node:path";
10	import { createHash } from "node:crypto";
11	import { conventionalCommitMessage } from "../git.js";
12	import { redactSecrets } from "../ui.js";
13	import { clearStaleEntry, removeOne, resolveBranchName, shownBranch, shownPath, statusOf, integratedReason, WorktreeError, type CommandResult, type WorktreeContext } from "./core.js";
14	import { git, gitOut, parseSubmoduleStatus, printable } from "./git.js";
15	import { currentEntry, defaultBranch, openRepo, resolveBranchCommit, type Repo, type WorktreeEntry } from "./repo.js";
16	import { readRegistry, updateRegistry, MAX_RECORDS, MAX_BRANCH_LENGTH } from "./registry.js";
17	import { hasVerification, NEXUS_STATE_PATH, workingState } from "./verification.js";
18	
19	export interface MergeOptions {
20	  target?: string;
21	  noSquash?: boolean;
22	  noRebase?: boolean;
23	  noRemove?: boolean;
24	  message?: string;
25	  /** Merge without a recorded verification; requires `reason`, which is recorded. */
26	  noVerifyReceipt?: boolean;
27	  reason?: string;
28	  /** Rewrite the message of a lone clean commit with `message` (the model path only; a plain `-m` leaves it alone). */
29	  amendSingleCommit?: boolean;
30	  /** The working state the message was written for: the merge refuses if the state is no longer exactly this. */
31	  expectedState?: { branch: string; head: string; tree: string };
32	}
33	
34	const NON_INTERACTIVE = { GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" };
35	
36	/**
37	 * Where WP-1313's blocking pre-merge hook attaches: called once, after every refusal (main checkout, detached HEAD,
38	 * target not checked out, operation in progress, dirty target, unresolved conflicts) and before anything is backed up,
39	 * committed, squashed or rebased. Exposed as an object so tests can observe it; not an extension point for callers.
40	 */
41	export const mergeSeams: { preMerge?: (info: { branch: string; target: string }) => void } = {};
42	
43	/** The initialised submodules of the worktree (one `git submodule status --recursive` call). */
44	function initializedSubmodules(dir: string): string[] {
45	  return parseSubmoduleStatus(git(dir, ["submodule", "status", "--recursive"], { allowFailure: true }).stdout).filter((sub) => sub.initialised).map((sub) => sub.path);
46	}
47	
48	/**
49	 * Of the initialised submodules, those with a local commit (HEAD, branch, tag or stash) that is on no remote-tracking branch
50	 * of that submodule. Their objects live in this worktree's own administrative directory, so removing the worktree would
51	 * delete the only copy while the target keeps pointing at it.
52	 */
53	function unpublishedSubmodules(dir: string, initialised: string[] = initializedSubmodules(dir)): string[] {
54	  return initialised.filter((sub) => {
55	    const local = git(path.join(dir, sub), ["rev-list", "-n", "1", "HEAD", "--branches", "--tags", "--glob=refs/stash*", "--not", "--remotes"], { allowFailure: true });
56	    return local.status !== 0 || Boolean(local.stdout.trim());
57	  });
58	}
59	
60	/** True when the entry is an automated task worktree (branch `nexus/<id>` under `.nexus/worktrees/`). */
61	function isSpeculativeEntry(repo: Repo, entry: { branch?: string | null; path: string }): boolean {
62	  const taskBase = path.join(repo.repoPath, ".nexus", "worktrees") + path.sep;
63	  return Boolean(entry.branch?.startsWith("nexus/") && entry.path.startsWith(taskBase));
64	}
65	
66	/** Paths `git status` reports for the worktree, read through the pinned helper (no shell, no fsmonitor, no hooks). */
67	function changedFiles(dir: string): string[] {
68	  const records = git(dir, ["status", "--porcelain=v1", "-z", "--untracked-files=normal"]).stdout.split("\0").filter(Boolean);
69	  const files: string[] = [];
70	  for (let i = 0; i < records.length; i++) {
71	    const record = records[i];
72	    files.push(record.slice(3));
73	    if (record[0] === "R" || record[0] === "C") i++; // the rename source follows as its own record
74	  }
75	  return files;
76	}
77	
78	interface InProgressOp { op: string; cmd: string }
79	
80	function inProgress(gitDir: string): InProgressOp | undefined {
81	  if (fs.existsSync(path.join(gitDir, "rebase-merge")) || fs.existsSync(path.join(gitDir, "rebase-apply"))) {
82	    return { op: "rebase", cmd: "git rebase --continue / --abort" };
83	  }
84	  if (fs.existsSync(path.join(gitDir, "MERGE_HEAD"))) {
85	    return { op: "merge", cmd: "git merge --continue / --abort" };
86	  }
87	  if (fs.existsSync(path.join(gitDir, "CHERRY_PICK_HEAD"))) {
88	    return { op: "cherry-pick", cmd: "git cherry-pick --continue / --abort" };
89	  }
90	  if (fs.existsSync(path.join(gitDir, "REVERT_HEAD")) || fs.existsSync(path.join(gitDir, "sequencer"))) {
91	    return { op: "revert", cmd: "git revert --continue / --abort" };
92	  }
93	  return undefined;
94	}
95	
96	/**
97	 * The backup ref of a branch: `refs/nexus-backup/<readable name>-<12 hex of sha1(branch)>`. One flat component, so
98	 * `foo` and `foo/bar` (which Git cannot hold as refs side by side) never collide, and the hash keeps names that
99	 * sanitise alike apart. List them with `git for-each-ref refs/nexus-backup`.
100	 */
101	export function backupRef(branch: string): string {
102	  const readable = branch.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[.-]+/, "").slice(0, 40) || "branch";
103	  return `refs/nexus-backup/${readable}-${createHash("sha1").update(branch).digest("hex").slice(0, 12)}`;
104	}
105	
106	/** A commit holding the worktree exactly as `git add -A` would see it, stored at backupRef(branch). */
107	function backup(dir: string, branch: string, dirty: boolean): string {
108	  let sha = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
109	  if (dirty) {
110	    const tree = workingState(dir, dirty).tree;
111	    sha = gitOut(dir, ["commit-tree", tree, "-p", sha, "-m", `nexus backup of ${branch} before merge`]);
112	  }
113	  git(dir, ["update-ref", "-m", "nexus: backup before merge", backupRef(branch), sha]);
114	  return sha;
115	}
116	
117	export interface MergeContextInfo {
118	  repo: ReturnType<typeof openRepo>;
119	  source: WorktreeEntry & { branch: string };
120	  branch: string;
121	  targetName: string;
122	  targetEntry: WorktreeEntry;
123	  targetSha: string;
124	  state: ReturnType<typeof statusOf>;
125	  gateState: ReturnType<typeof workingState>;
126	  waiver?: string;
127	  mergeBase: string;
128	  ahead: number;
129	}
130	
131	/**
132	 * Whether this merge will write a commit message at all, so a caller that has to produce one (the model) asks only
133	 * when it is used: uncommitted changes are committed; a clean branch is squashed (more than one commit) or, on the
134	 * model path, its lone commit is amended; commits that cancel each other out merge as a no-op and need no message.
135	 */
136	export function writesCommitMessage(mctx: MergeContextInfo, options: MergeOptions): boolean {
137	  if (mctx.state.total > 0) return true;
138	  if (mctx.ahead === 0) return false;
139	  const tree = (rev: string) => gitOut(mctx.source.path, ["rev-parse", "--verify", "--end-of-options", `${rev}^{tree}`]);
140	  if (tree("HEAD") === tree(mctx.mergeBase)) return false; // cancelled
141	  return (mctx.ahead > 1 && !options.noSquash) || (mctx.ahead === 1 && options.amendSingleCommit === true);
142	}
143	
144	export function resolveMergeContext(ctx: WorktreeContext, options: MergeOptions = {}): MergeContextInfo {
145	  const repo = openRepo(ctx.cwd);
146	  const source = currentEntry(repo);
147	  if (!source || source.isMain) throw new WorktreeError("run `worktree merge` from inside the worktree you want to merge, not the main checkout");
148	  if (!source.branch) throw new WorktreeError("the current worktree is on a detached HEAD; create a branch first");
149	  const branch = source.branch;
150	  if (branch.length > MAX_BRANCH_LENGTH) {
151	    throw new WorktreeError(`branch name is too long (${branch.length} characters; maximum ${MAX_BRANCH_LENGTH})`);
152	  }
153	  if (isSpeculativeEntry(repo, source)) {
154	    throw new WorktreeError(`the current worktree is a speculative task worktree (${shownBranch(branch)}); speculative worktrees cannot be merged with \`worktree merge\``);
155	  }
156	  const targetName = options.target ? resolveBranchName(repo, options.target) : defaultBranch(repo);
157	  if (!targetName) throw new WorktreeError("this repository has no default branch to merge into; pass a target");
158	  if (targetName === branch) throw new WorktreeError("the target is the branch being merged");
159	  const targetEntry = repo.entries.find((entry) => entry.branch === targetName);
160	  if (!targetEntry || targetEntry.prunable) throw new WorktreeError(`target ${shownBranch(targetName)} is not checked out in any worktree; run \`worktree switch ${shownBranch(targetName)}\` first`);
161	  if (isSpeculativeEntry(repo, targetEntry)) {
162	    throw new WorktreeError(`target ${shownBranch(targetName)} is a speculative task worktree; speculative worktrees cannot be merged into`);
163	  }
164	
165	  const gitDir = gitOut(source.path, ["rev-parse", "--path-format=absolute", "--git-dir"]);
166	  const busy = inProgress(gitDir);
167	  if (busy) throw new WorktreeError(`a ${busy.op} is already in progress in this worktree; finish it (${busy.cmd}) and run merge again`);
168	  const targetState = statusOf(targetEntry.path);
169	  if (targetState.total > 0) throw new WorktreeError(`the target worktree (${shownBranch(targetName)}) has uncommitted changes; commit or stash them first`);
170	
171	  const state = statusOf(source.path);
172	  // A conflicted `git stash pop` leaves unmerged index entries with no operation marker; staging them would
173	  // clear the conflict and commit the markers.
174	  if (state.conflicted > 0) throw new WorktreeError(`the worktree has ${state.conflicted} path(s) with unresolved conflicts; resolve them (or \`git restore\` them) in ${shownPath(ctx.home, source.path)} and run merge again. Nothing was changed`);
175	  const targetSha = resolveBranchCommit(repo, targetName);
176	  if (!targetSha) throw new WorktreeError(`target ${shownBranch(targetName)} does not name a commit`);
177	
178	  // Receipt gate (the named-worktree equivalent of CAND-003): the exact state being merged needs a recorded passing
179	  // verification, or an explicit operator waiver with a reason. Checked before anything is changed.
180	  const gateState = workingState(source.path, state.total > 0);
181	  const registry = readRegistry(repo.commonDir).registry;
182	  let waiver: string | undefined;
183	  if (!hasVerification(registry, branch, gateState)) {
184	    if (!options.noVerifyReceipt) {
185	      throw new WorktreeError(
186	        `no recorded passing verification for ${shownBranch(branch)} at ${gateState.head.slice(0, 12)}${gateState.dirty ? " plus uncommitted changes" : ""}. ` +
187	        "Run your verifier in this worktree through a Nexus session, or merge anyway with --no-verify-receipt --reason \"why\" (the reason is recorded).");
188	    }
189	    const reason = redactSecrets((options.reason ?? "").trim()).slice(0, 200);
190	    if (reason.length < 3) throw new WorktreeError("--no-verify-receipt needs --reason \"why\" (at least 3 characters); it is recorded");
191	    waiver = reason;
192	  }
193	
194	  const mergeBase = gitOut(source.path, ["merge-base", targetSha, "HEAD"]);
195	  const ahead = Number(gitOut(source.path, ["rev-list", "--count", `${mergeBase}..HEAD`]));
196	
197	  return {
198	    repo,
199	    source: source as WorktreeEntry & { branch: string },
200	    branch,
201	    targetName,
202	    targetEntry,
203	    targetSha,
204	    state,
205	    gateState,
206	    waiver,
207	    mergeBase,
208	    ahead,
209	  };
210	}
211	
212	export function mergeWorktree(ctx: WorktreeContext, options: MergeOptions = {}): CommandResult {
213	  const mctx = resolveMergeContext(ctx, options);
214	  const { repo, source, branch, targetName, targetEntry, targetSha, state, gateState, waiver, mergeBase, ahead } = mctx;
215	
216	  if (options.expectedState && (options.expectedState.branch !== branch || options.expectedState.head !== gateState.head || options.expectedState.tree !== gateState.tree)) {
217	    throw new WorktreeError("the worktree (its branch, HEAD or content) changed while the commit message was being written; nothing was merged. Run the command again");
218	  }
219	
220	  const notes: string[] = [];
221	  if (waiver !== undefined) {
222	    notes.push(`Merging without a verification record (waiver recorded: ${waiver}).`);
223	  }
224	  const dirty = state.total > 0;
225	
226	  mergeSeams.preMerge?.({ branch, target: targetName });
227	
228	  if (!dirty && ahead === 0) {
229	    notes.push(`Nothing to merge: ${shownBranch(branch)} has no commits beyond ${shownBranch(targetName)}.`);
230	  } else {
231	    backup(source.path, branch, dirty);
232	    notes.push(`Backed up ${shownBranch(branch)} to ${backupRef(branch)}.`);
233	  }
234	
235	  if (dirty) {
236	    const message = options.message ?? conventionalCommitMessage(changedFiles(source.path));
237	    // Internal Nexus state is never committed by the merge (the same exclusion `/commit` applies).
238	    git(source.path, ["add", "-A"]);
239	    git(source.path, ["reset", "-q", "HEAD", "--", NEXUS_STATE_PATH], { allowFailure: true });
240	    // The receipt covers the state that was checked. A save that landed since (an editor, another session) is not part of
241	    // it: nothing is committed on its strength. A waiver covers whatever is there.
242	    if (waiver === undefined && gitOut(source.path, ["write-tree"]) !== gateState.tree) {
243	      git(source.path, ["reset", "-q"], { allowFailure: true });
244	      throw new WorktreeError("the working tree changed after the verification receipt was checked; nothing was committed or merged. Verify the current state (or review it and merge with --no-verify-receipt --reason \"why\")");
245	    }
246	    if (git(source.path, ["diff", "--cached", "--quiet"], { allowFailure: true }).status === 0) {
247	      notes.push("Nothing the superproject can commit was changed (for example only edits inside a submodule).");
248	    } else {
249	      git(source.path, ["commit", "-m", message], { env: NON_INTERACTIVE });
250	      notes.push("Committed the uncommitted changes.");
251	    }
252	  }
253	
254	  if (waiver === undefined && !dirty && gitOut(source.path, ["rev-parse", "--verify", "HEAD"]) !== gateState.head) {
255	    throw new WorktreeError("a commit landed in the worktree after the verification receipt was checked; nothing was merged. Verify the current state and run the command again");
256	  }
257	
258	  // A clean source has an index equal to HEAD; anything staged since the snapshot (an `add -f` of an ignored file) would
259	  // be committed by the squash or amend below, or lost with the worktree.
260	  if (!dirty && gitOut(source.path, ["write-tree"]) !== gitOut(source.path, ["rev-parse", "--verify", "HEAD^{tree}"])) {
261	    throw new WorktreeError("the index changed after the state snapshot (something was staged in the worktree); nothing was merged. Review it and run the command again");
262	  }
263	
264	  const count = Number(gitOut(source.path, ["rev-list", "--count", `${mergeBase}..HEAD`]));
265	  const treeOf = (rev: string) => gitOut(source.path, ["rev-parse", "--verify", "--end-of-options", `${rev}^{tree}`]);
266	  // Commits that cancel each other (a change and its revert) add nothing: squashing them would leave an empty commit
267	  // and rewriting them onto the target would only add noise, so they are left where they are and not merged.
268	  const cancelled = count > 0 && treeOf("HEAD") === treeOf(mergeBase);
269	  const nothingToMerge = !dirty && ahead === 0; // reported above: the rebase and fast-forward below have nothing to carry
270	  if (cancelled) notes.push(`The ${count} commit(s) on ${shownBranch(branch)} cancel each other out: nothing to merge into ${shownBranch(targetName)}.`);
271	  if (!cancelled && count > 1 && !options.noSquash) {
272	    const subjects = gitOut(source.path, ["log", "--reverse", "--format=%s", `${mergeBase}..HEAD`]).split("\n").filter(Boolean);
273	    const message = options.message ?? `${subjects[0]}\n\nSquashed ${count} commits from ${branch}:\n${subjects.map((s) => `- ${s}`).join("\n")}`;
274	    git(source.path, ["reset", "--soft", mergeBase]);
275	    git(source.path, ["commit", "-m", message], { env: NON_INTERACTIVE });
276	    notes.push(`Squashed ${count} commits.`);
277	  } else if (!cancelled && !dirty && count === 1 && options.message && options.amendSingleCommit) {
278	    git(source.path, ["commit", "--amend", "-m", options.message], { env: NON_INTERACTIVE });
279	  }
280	
281	  if (!cancelled && !nothingToMerge && !options.noRebase && mergeBase !== targetSha) {
282	    // `--autostash`: tracked `.nexus` state stays edited (and uncommitted) in the worktree, which a rebase otherwise refuses.
283	    // A plain rebase linearises the range and drops merge commits together with any edit only they carry (a conflict
284	    // resolution, for one). Squashing (the default) keeps the tree; without it such a history is refused.
285	    if (Number(gitOut(source.path, ["rev-list", "--merges", "--count", `${mergeBase}..HEAD`])) > 0) {
286	      throw new WorktreeError(`${shownBranch(branch)} contains merge commits and the target has moved, so rebasing without squashing would drop edits that only the merge commits carry; merge without --no-squash, or rebase ${shownBranch(branch)} onto ${shownBranch(targetName)} yourself first. Nothing was merged`);
287	    }
288	    const rebase = git(source.path, ["rebase", "--autostash", targetSha], { allowFailure: true, env: NON_INTERACTIVE });
289	    if (rebase.status !== 0) {
290	      const open = inProgress(gitOut(source.path, ["rev-parse", "--path-format=absolute", "--git-dir"]));
291	      if (!open) throw new WorktreeError(`rebase onto ${shownBranch(targetName)} failed: ${printable(redactSecrets(rebase.stderr.trim().split("\n")[0] ?? ""))}`);
292	      const files = git(source.path, ["diff", "--name-only", "--diff-filter=U"], { allowFailure: true }).stdout.split("\n").filter(Boolean).slice(0, 10);
293	      return {
294	        success: false,
295	        output: `Rebase onto ${shownBranch(targetName)} stopped on conflicts${files.length ? ` in ${files.map((f) => printable(redactSecrets(f))).join(", ")}` : ""}.\n` +
296	          `The rebase is left open in ${shownPath(ctx.home, source.path)}: resolve the files, run \`git rebase --continue\` there and merge again, or \`git rebase --abort\` to undo it. ${targetName} was not changed.`,
297	      };
298	    }
299	    notes.push(`Rebased onto ${shownBranch(targetName)}.`);
300	  }
301	
302	  if (!cancelled && !nothingToMerge) {
303	    // Another terminal may have switched the target checkout since it was chosen: never advance another branch under this name.
304	    const targetRef = git(targetEntry.path, ["symbolic-ref", "--quiet", "HEAD"], { allowFailure: true }).stdout.trim();
305	    if (targetRef !== `refs/heads/${targetName}`) {
306	      const targetNow = targetRef.replace(/^refs\/heads\//, "");
307	      throw new WorktreeError(`the target checkout ${shownPath(ctx.home, targetEntry.path)} is no longer on ${shownBranch(targetName)} (it is on ${targetNow ? shownBranch(targetNow) : "a detached HEAD"}); nothing was fast-forwarded. The source branch is intact and backed up at ${backupRef(branch)}; switch the target back and run merge again`);
308	    }
309	    // `refs/heads/<branch>`, not the short name: a tag of the same name would otherwise be what gets merged.
310	    // `--no-overwrite-ignore` prevents fast-forwarding over an untracked ignored file in the target.
311	    const ff = git(targetEntry.path, ["merge", "--ff-only", "--no-edit", "--no-overwrite-ignore", "--end-of-options", `refs/heads/${branch}`], { allowFailure: true, env: NON_INTERACTIVE });
312	    if (ff.status !== 0) {
313	      const errDetail = ff.stderr ? printable(redactSecrets(ff.stderr.trim().split("\n")[0] ?? "")) : "";
314	      if (errDetail && (errDetail.toLowerCase().includes("overwrite") || errDetail.toLowerCase().includes("untracked working tree file"))) {
315	        throw new WorktreeError(`could not fast-forward ${shownBranch(targetName)} to ${shownBranch(branch)}: ${errDetail}`);
316	      }
317	      throw new WorktreeError(`could not fast-forward ${shownBranch(targetName)} to ${shownBranch(branch)}: ${options.noRebase ? "the branch is not a descendant of the target (merge without --no-rebase)" : "the target moved while merging; run merge again"}`);
318	    }
319	    notes.push(`Fast-forwarded ${shownBranch(targetName)}.`);
320	  }
321	
322	  if (waiver !== undefined) {
323	    const reason = waiver;
324	    try {
325	      updateRegistry(repo.commonDir, (reg) => {
326	        reg.waivers = [...(reg.waivers ?? []), { branch, head: gateState.head, reason, recordedAt: new Date().toISOString() }].slice(-MAX_RECORDS);
327	      });
328	    } catch (err) {
329	      // The target has already advanced: report the merge, and say the audit record is missing.
330	      notes.push(`The waiver could not be recorded in the registry (${redactSecrets((err as Error).message).slice(0, 150)}).`);
331	    }
332	  }
333	
334	  if (!options.noRemove) {
335	    // The merged work is on the target. Only ignored output (build caches) may still be in the worktree; it goes with
336	    // it. Anything else left (edits inside a submodule cannot be committed from here, for one) is never forced away.
337	    let left: ReturnType<typeof statusOf> | undefined; // undefined: the inspection itself failed
338	    let initialized: string[];
339	    let unpublished: string[];
340	    try {
341	      left = statusOf(source.path, { ignoreSubmodules: "none" });
342	      initialized = left.total > 0 ? [] : initializedSubmodules(source.path); // one `git submodule status` for both notes
343	      unpublished = unpublishedSubmodules(source.path, initialized);
344	    } catch (err) {
345	      // The merge is done; whatever stops the safety checks keeps the worktree rather than failing the report.
346	      left = undefined;
347	      initialized = [];
348	      unpublished = [];
349	      notes.push(`Could not inspect the worktree after the merge (${redactSecrets((err as Error).message).slice(0, 150)}).`);
350	    }
351	    if (unpublished.length > 0) {
352	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: submodule ${unpublished.map((sub) => printable(redactSecrets(sub))).join(", ")} has a commit that is on no remote branch, and removing the worktree would delete its only copy. Push it from there, then run \`worktree remove\`. The merge itself is done.`);
353	    } else if (left === undefined) {
354	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: it could not be inspected, so nothing was deleted. The merge itself is done.`);
355	    } else if (left.total > 0) {
356	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: ${left.total} uncommitted change(s) remain that the merge could not carry (check \`git status\` there, submodules included). Nothing was deleted.`);
357	    } else if (initialized.length > 0) {
358	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: submodule ${initialized.map((sub) => printable(redactSecrets(sub))).join(", ")} is initialized here; removing it requires \`worktree remove --force\` after verifying submodule state. The merge itself is done.`);
359	    } else {
360	      try {
361	        notes.push(removeOne({ ...ctx, cwd: targetEntry.path }, source.path, { discardIgnored: true, target: targetName }));
362	      } catch (err) {
363	        notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: removal failed (${redactSecrets((err as Error).message).slice(0, 150)}). The merge itself is done.`);
364	      }
365	    }
366	  }
367	
368	  const removedPath = !fs.existsSync(source.path) ? source.path : undefined;
369	  return { success: true, output: notes.join("\n"), data: { branch, target: targetName, targetPath: targetEntry.path, ...(removedPath ? { removedPath } : {}) } };
370	}
371	
372	// ---- prune ----------------------------------------------------------------------------------------------------
373	
374	export interface PruneOptions { dryRun?: boolean; minAgeMs?: number; limit?: number; discardIgnored?: boolean }
375	
376	const DAY_MS = 86_400_000;
377	const REPORT_LINES = 40;
378	
379	export function parseAge(text: string): number {
380	  const match = /^(\d+)([smhdw])$/.exec(text);
381	  if (!match) throw new WorktreeError("--min-age must look like 30m, 12h, 1d or 2w");
382	  const unit = { s: 1000, m: 60_000, h: 3_600_000, d: DAY_MS, w: 7 * DAY_MS }[match[2] as "s"];
383	  return Number(match[1]) * unit;
384	}
385	
386	export function pruneWorktrees(ctx: WorktreeContext, options: PruneOptions = {}): CommandResult {
387	  const minAge = options.minAgeMs ?? DAY_MS;
388	  const limit = Math.max(1, options.limit ?? 100);
389	  const repo = openRepo(ctx.cwd);
390	  const here = currentEntry(repo);
391	  const target = defaultBranch(repo);
392	  const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
393	  if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");
394	
395	  const lines: string[] = [];
396	  const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
397	  let limited = false;
398	  const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
399	  const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
400	  const now = Date.now();
401	
402	  for (const entry of repo.entries) {
403	    if (entry.isMain || entry === here) continue;
404	    if (counts.removed >= limit) { limited = true; break; }
405	    if (entry.prunable && entry.locked) { keep(entry, "stale but locked"); continue; }
406	    if (entry.prunable) {
407	      // A hand-deleted worktree is judged like any other. A detached one may hold the only reference to commits in its
408	      // administrative HEAD and reflog, so it goes only if that HEAD is integrated and old enough; a branch worktree's
409	      // commits live on its branch, which stays. Only the selected entries are cleared, never a global `worktree prune`.
410	      try {
411	        const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000;
412	        if (entry.detached && now - stamp < minAge) { counts.young++; continue; }
413	        const reason = entry.detached ? integratedReason(repo, entry.head, targetSha) : "branch kept";
414	        if (!reason) { keep(entry, `stale, but its detached HEAD is not merged into ${shownBranch(target!)}`); continue; }
415	        if (!options.dryRun) clearStaleEntry(repo, entry);
416	        counts.stale++;
417	        counts.removed++;
418	        lines.push(`${options.dryRun ? "would clear" : "cleared"} stale ${label(entry)} (${reason})`);
419	      } catch (err) {
420	        keep(entry, redactSecrets((err as Error).message).slice(0, 160));
421	      }
422	      continue;
423	    }
424	    if (entry.locked) { keep(entry, "locked"); continue; }
425	    if (isSpeculativeEntry(repo, entry)) { keep(entry, "speculative task worktree"); continue; }
426	    try {
427	      const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
428	      if (now - touched < minAge) { counts.young++; continue; }
429	      const reason = integratedReason(repo, entry.head, targetSha);
430	      if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
431	      const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
432	      if (dirty.total > 0) { keep(entry, `dirty (${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked)`); continue; }
433	      if (dirty.ignored > 0 && !options.discardIgnored) { keep(entry, `${dirty.ignored} ignored path(s); pass --discard-ignored to prune it anyway`); continue; }
434	      if (options.dryRun) {
435	        counts.removed++;
436	        lines.push(`would remove ${label(entry)} (integrated: ${reason})`);
437	        continue;
438	      }
439	      removeOne(ctx, entry.path, { discardIgnored: dirty.ignored > 0 });
440	      counts.removed++;
441	      lines.push(`removed ${label(entry)} (integrated: ${reason})`);
442	    } catch (err) {
443	      keep(entry, redactSecrets((err as Error).message).slice(0, 160));
444	    }
445	  }
446	
447	  const summary = `${options.dryRun ? "Would remove" : "Removed"} ${counts.removed}, kept ${counts.kept}, ${counts.young} younger than the minimum age${counts.stale ? `, ${counts.stale} stale registration(s) ${options.dryRun ? "would be pruned" : "pruned"}` : ""}.`;
448	  const shown = lines.slice(0, REPORT_LINES);
449	  if (lines.length > REPORT_LINES) shown.push(`... ${lines.length - REPORT_LINES} more lines`);
450	  if (limited) shown.push(`stopped at the limit of ${limit} removals; run prune again for more`);
451	  return { success: true, output: [...shown, summary].join("\n"), data: { ...counts, limited } };
452	}
